content.query:
let r = requests | where timestamp {TimeRange} | where url !endswith '/robots933456.txt';
let total = toscalar(r | count);
let failedPct = toscalar(r | summarize iff(count() == 0, 0.0, round(100.0 * countif(success == false) / count(), 2)));
let p95 = toscalar(r | summarize round(percentile(duration, 95), 0));
let apiExceptions = toscalar(exceptions | where timestamp {TimeRange} | where cloud_RoleName != "CheckMate.Web" | count);
let webExceptions = toscalar(exceptions | where timestamp {TimeRange} | where cloud_RoleName == "CheckMate.Web" | count);
let pv = pageViews | where timestamp {TimeRange};
let viewCount = toscalar(pv | count);
let users = toscalar(pv | summarize dcount(user_Id));
let sessions = toscalar(pv | summarize dcount(session_Id));
union
    (print Order = 1, Metric = "API requests", Value = tostring(total), Health = "Info"),
    (print Order = 2, Metric = "Failed requests", Value = strcat(failedPct, "%"),
        Health = case(failedPct >= 5, "Critical", failedPct >= 1, "Warning", "Healthy")),
    (print Order = 3, Metric = "P95 response time", Value = strcat(coalesce(p95, 0.0), " ms"),
        Health = case(isnull(p95), "Info", p95 >= 3000, "Critical", p95 >= 1000, "Warning", "Healthy")),
    (print Order = 4, Metric = "API exceptions", Value = tostring(apiExceptions),
        Health = case(apiExceptions >= 10, "Critical", apiExceptions > 0, "Warning", "Healthy")),
    (print Order = 5, Metric = "Browser exceptions", Value = tostring(webExceptions),
        Health = case(webExceptions >= 10, "Critical", webExceptions > 0, "Warning", "Healthy")),
    (print Order = 6, Metric = "Page views", Value = tostring(viewCount), Health = "Info"),
    (print Order = 7, Metric = "Users", Value = tostring(users), Health = "Info"),
    (print Order = 8, Metric = "Sessions", Value = tostring(sessions), Health = "Info")
| order by Order asc
| project Metric, Value, Health

pageViews
| where timestamp {TimeRange}
| summarize Views = count(), Users = dcount(user_Id) by bin(timestamp, {TimeRange:grain})

pageViews
| where timestamp {TimeRange}
| summarize Views = count(), Users = dcount(user_Id), Sessions = dcount(session_Id) by bin(timestamp, {TimeRange:grain})
